"use client"

import * as React from "react"
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle"
import { ToggleGroup as ToggleGroupPrimitive } from "@base-ui/react/toggle-group"
import { type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { toggleVariants, toggleSizeClasses } from "./toggle"

/*
 * The container is the recessed "track": deep top inset shadow + soft
 * bottom highlight. Items are the same pill primitives as <Toggle>.
 */

type Size = keyof typeof toggleSizeClasses

const ToggleGroupContext = React.createContext<{
  variant: VariantProps<typeof toggleVariants>["variant"]
  size: Size
}>({
  variant: "default",
  size: "default",
})

interface ToggleGroupRootProps
  extends Omit<ToggleGroupPrimitive.Props, "className">,
    VariantProps<typeof toggleVariants> {
  size?: Size
  className?: string
}

const ToggleGroup = React.forwardRef<HTMLDivElement, ToggleGroupRootProps>(
  ({ className, variant, size = "default", children, ...props }, ref) => (
    <ToggleGroupPrimitive
      ref={ref}
      className={cn(
        "inline-flex items-center p-1 rounded-[0.75rem] bg-card",
        "[box-shadow:var(--shadow-inset)]",
        className
      )}
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size }}>
        {children}
      </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive>
  )
)
ToggleGroup.displayName = "ToggleGroup"

interface ToggleGroupItemProps
  extends Omit<TogglePrimitive.Props, "className">,
    VariantProps<typeof toggleVariants> {
  size?: Size
  className?: string
}

const ToggleGroupItem = React.forwardRef<
  HTMLButtonElement,
  ToggleGroupItemProps
>(({ className, children, variant, size, ...props }, ref) => {
  const ctx = React.useContext(ToggleGroupContext)
  const resolvedSize = size ?? ctx.size
  return (
    <TogglePrimitive
      ref={ref}
      className={cn(
        toggleVariants({ variant: variant ?? ctx.variant }),
        toggleSizeClasses[resolvedSize],
        className
      )}
      {...props}
    >
      {children}
    </TogglePrimitive>
  )
})
ToggleGroupItem.displayName = "ToggleGroupItem"

export { ToggleGroup, ToggleGroupItem }
